arguments:
{"script":"# Prepare admin parsed
awk -F: 'NF>=3{gsub(/^[ \t]+|[ \t]+$/,"",$1); gsub(/^[ \t]+|[ \t]+$/,"",$3); gsub(/^[ \t]+|[ \t]+$/,"",$4); print $1","$3","$4}' group_check_workspace/admin_group_overrides.txt > group_check_workspace/admin_parsed.csv || true
# Sort
sort -t, -k1,1 group_check_workspace/groups_parsed.csv > group_check_workspace/base_sorted.csv
sort -t, -k1,1 group_check_workspace/admin_parsed.csv > group_check_workspace/admin_sorted.csv
# Join
join -t, -a1 -a2 -o 0,1.2,1.3,2.2,2.3 group_check_workspace/base_sorted.csv group_check_workspace/admin_sorted.csv 2>/dev/null > group_check_workspace/joined.csv || true
: > group_check_workspace/merge_conflicts.log
awk -F, 'BEGIN{OFS=","} {
 name=$1; base_gid=$2; base_mem=$3; admin_gid=$4; admin_mem=$5;
 if(admin_gid!=""){
   if(base_gid=="" && base_mem==""){
     print name,admin_gid,admin_mem
   } else {
     if(base_gid!=admin_gid || base_mem!=admin_mem){
       print name ": base(" base_gid "," base_mem ") vs admin(" admin_gid "," admin_mem ")" >> "group_check_workspace/merge_conflicts.log"
     }
     gid = (admin_gid!=""?admin_gid:base_gid);
     mem = (admin_mem!=""?admin_mem:base_mem);
     print name,gid,mem
   }
 } else {
   print name,base_gid,base_mem
 }
}' group_check_workspace/joined.csv > group_check_workspace/merged.csv
# If merged empty, fallback
if [ ! -s group_check_workspace/merged.csv ]; then cp group_check_workspace/base_sorted.csv group_check_workspace/merged.csv; fi
sed -n '1,20p' group_check_workspace/merged.csv"}

